// The system the reel builds: a real-time messaging platform, grown from one server
// into a global, multi-region system. Every link is a real data path (who calls whom);
// components are named by role, implemented with technologies from the CV.
//
// Layout: a grid of rows front → back (clients nearest the camera, storage and
// outbound workers furthest). Links only join neighbouring rows or neighbouring tiles,
// so no line ever appears to connect components that don't talk to each other.
import { STAGES, T } from './timeline.js';
import { clamp, ease, prog } from './util.js';

