const REGIONS = ['A', 'B', 'C'];
// Regions B and C divide off region A: back-left and back-right in 16:9, behind in 9:16.
const OFFSETS = {
  landscape: { A: [0, 0], B: [-1350, -1150], C: [1350, -1150] },
  portrait: { A: [0, 0], B: [0, -1150], C: [0, -2300] },
};
const GROUP_AT = { k8s: 10.8, aws: 10.9 };
const STATUS_AT = 11.3; // observability lights a status dot on each workload
const SPLIT_MOVE = 1.0;

export const buildGraph = (format) => {
  const portrait = format === 'portrait';
  const nodes = [];
  const byId = new Map();
  const add = (n) => {
    nodes.push(n);
    byId.set(n.id, n);
    return n;
  };

  GLOBAL.forEach(([id, kind, label, sub, glyph, t0, l, p]) => {
    add({ id, kind, label, sub, glyph, at: t0, stackAt: 0, base: at(...(portrait ? p : l)), moved: null, region: null, status: kind !== 'client' && kind !== 'external' });
  });
  const depthOrder = (r) => r; // clones peel away front to back
  REGIONS.forEach((region) => {
    const off = OFFSETS[format][region];
    REGIONAL.forEach(([id, kind, label, sub, glyph, t0, stackAt, [c, r]]) => {
      const base = at(c, r);
      const stagger = region === 'A' ? 0 : (depthOrder(r) - 2) * 0.05 + (region === 'C' ? 0.08 : 0);
      add({
        id: region === 'A' ? id : `${id}@${region}`,
        key: id,
        kind,
        label,
        sub,
        glyph,
        at: region === 'A' ? t0 : T.split + stagger,
        stackAt: region === 'A' ? stackAt : stackAt ? T.split : 0,
        base: [base[0] + off[0], base[1] + off[1]],
        origin: region === 'A' ? null : base,
        region,
        status: true,
      });
    });
  });

  // Group boxes are fitted around region A's components, then offset for each region.
  const regionA = nodes.filter((n) => n.region === 'A');
  const boxOf = (list, pad) => {
    let x0 = Infinity;
    let y0 = Infinity;
    let x1 = -Infinity;
    let y1 = -Infinity;
    list.forEach((n) => {
      x0 = Math.min(x0, n.base[0] - CARD.w * 0.55);
      x1 = Math.max(x1, n.base[0] + CARD.w * 0.55);
      y0 = Math.min(y0, n.base[1] - CARD.h * 0.55);
      y1 = Math.max(y1, n.base[1] + CARD.h * 0.55);
    });
    return [x0 - pad, y0 - pad - 26, x1 + pad, y1 + pad];
  };
  const BOXES = {
    k8s: boxOf(regionA.filter((n) => n.key !== 'lb'), 26),
    aws: boxOf(regionA, 56),
  };
  const groups = [];
  REGIONS.forEach((region) => {
    const off = OFFSETS[format][region];
    const clone = region !== 'A';
    ['aws', 'k8s'].forEach((type) => {
      const [x0, y0, x1, y1] = BOXES[type];
      groups.push({
        id: region === 'A' ? type : `${type}@${region}`,
        type,
        region,
        at: clone ? T.split : GROUP_AT[type],
        rect: [x0 + off[0], y0 + off[1], x1 + off[0], y1 + off[1]],
        origin: clone ? [x0, y0, x1, y1] : null,
        label: type === 'k8s' ? 'Kubernetes · irfanck-prod' : 'AWS',
        regionLabel: `Region ${REGIONS.indexOf(region) + 1}`,
      });
    });
  });
  const groupById = new Map(groups.map((g) => [g.id, g]));

  const regionalIds = new Set(REGIONAL.map((r) => r[0]));
  const groupIds = new Set(['k8s', 'aws']);
  const inRegion = (id, region) => (regionalIds.has(id) || groupIds.has(id) ? `${id}@${region}` : id);
  const edges = [];
  const addEdge = (from, to, style, t0, until = Infinity, extra = {}) => edges.push({ from, to, style, at: t0, until, ...extra, i: edges.length });
  EDGES.forEach(([from, to, style, t0, until]) => {
    addEdge(from, to, style, t0, until);
    if (until < T.split) return;
    const local = (id) => regionalIds.has(id) || groupIds.has(id);
    if (!local(from) && !local(to)) return; // purely global links exist once
    ['B', 'C'].forEach((region, k) => {
      const internal = local(from) && local(to);
      // Clones carry their internal wiring; links to shared components draw in once they land.
      addEdge(inRegion(from, region), inRegion(to, region), style, internal ? T.split + 0.05 + k * 0.08 : T.split + 1.25 + k * 0.1 + (edges.length % 7) * 0.04, Infinity, { cloned: internal });
    });
  });
  // Storage replicates across regions.
  addEdge('store', 'store@B', 'replica', T.split + 1.35);
  addEdge('store', 'store@C', 'replica', T.split + 1.4);
  addEdge('users', 'users@B', 'replica', T.split + 1.5);
  addEdge('users', 'users@C', 'replica', T.split + 1.55);

  const node = (id) => byId.get(id);
  const group = (id) => groupById.get(id);

  // ── State at time t ───────────────────────────────────────────────────────
  const nodeState = (n, t) => {
    const a = n.origin ? prog(t, n.at + 0.3, n.at + 0.7, ease.outCubic) : prog(t, n.at, n.at + 0.42, ease.outCubic);
    if (a <= 0) return null;
    let [x, y] = n.base;
    if (n.origin) {
      const m = prog(t, n.at, n.at + SPLIT_MOVE, ease.inOutCubic);
      x = n.origin[0] + (n.base[0] - n.origin[0]) * m;
      y = n.origin[1] + (n.base[1] - n.origin[1]) * m;
    } else if (n.moved) {
      const m = prog(t, T.split - 0.25, T.split + 0.75, ease.inOutCubic);
      x = n.base[0] + (n.moved[0] - n.base[0]) * m;
      y = n.base[1] + (n.moved[1] - n.base[1]) * m;
    }
    const s = n.origin ? 1 : 0.94 + 0.06 * ease.outBack(prog(t, n.at, n.at + 0.55));
    const stack = !n.stackAt ? 0 : n.origin ? 1 : prog(t, n.stackAt, n.stackAt + 0.5, ease.outCubic);
    const lit = n.origin ? n.at + 0.8 : STATUS_AT + clamp((n.base[1] + 700) / 1600) * 0.5;
    const status = n.status && t > lit ? prog(t, lit, lit + 0.3) : 0;
    const pulse = n.origin ? 0 : prog(t, n.at, n.at + 0.8);
    return { x, y, a, s, stack, status, pulse };
  };

  const groupState = (g, t) => {
    const a = g.origin ? prog(t, g.at + 0.3, g.at + 0.8, ease.outCubic) : prog(t, g.at, g.at + 0.6, ease.outCubic);
    if (a <= 0) return null;
    let [x0, y0, x1, y1] = g.rect;
    if (g.origin) {
      const m = prog(t, g.at, g.at + SPLIT_MOVE, ease.inOutCubic);
      [x0, y0, x1, y1] = g.origin.map((v, i) => v + (g.rect[i] - v) * m);
    }
    const grow = g.origin ? 0 : 1 - ease.outCubic(prog(t, g.at, g.at + 0.7));
    const regionLabel = prog(t, T.split + 0.6, T.split + 1.2);
    return { x0: x0 - grow * 24, y0: y0 - grow * 24, x1: x1 + grow * 24, y1: y1 + grow * 24, a, regionLabel };
  };

  const edgeState = (e, t) => {
    if (t < e.at || t > e.until + 0.5) return null;
    const draw = e.cloned ? 1 : prog(t, e.at, e.at + 0.5, ease.inOutCubic);
    const fadeOut = e.until < Infinity ? 1 - prog(t, e.until, e.until + 0.5) : 1;
    const a = (e.cloned ? prog(t, e.at, e.at + 0.3) : Math.min(1, draw * 3)) * fadeOut;
    const flow = prog(t, e.at + (e.cloned ? 0.9 : 0.5), e.at + (e.cloned ? 1.3 : 0.9)) * fadeOut;
    return { draw, a, flow };
  };

  // ── Camera framings: each stage frames everything built so far ───────────
  const settle = (n) => (n.moved ? n.moved : n.base);
  const bboxAt = (time, final) => {
    let x0 = Infinity;
    let y0 = Infinity;
    let x1 = -Infinity;
    let y1 = -Infinity;
    nodes.forEach((n) => {
      if (n.at > time) return;
      const [x, y] = final ? settle(n) : n.base;
      x0 = Math.min(x0, x - CARD.w / 2);
      x1 = Math.max(x1, x + CARD.w / 2);
      y0 = Math.min(y0, y - CARD.h / 2);
      y1 = Math.max(y1, y + CARD.h / 2);
    });
    groups.forEach((g) => {
      if (g.at > time) return;
      x0 = Math.min(x0, g.rect[0]);
      y0 = Math.min(y0, g.rect[1] - 30);
      x1 = Math.max(x1, g.rect[2]);
      y1 = Math.max(y1, g.rect[3]);
    });
    return [x0, y0, x1, y1];
  };
  const framings = STAGES.map((s, i) => {
    const next = STAGES[i + 1]?.at ?? Infinity;
    const regions = s.id === 'regions';
    return { at: i === 0 ? 0 : s.at - (regions ? 0.1 : 0.55), box: bboxAt(regions ? Infinity : next - 0.05, regions), dur: regions ? 1.9 : 1.2 };
  });

  // The rollout wave sweeps front to back across the finished system.
  const full = bboxAt(Infinity, true);
  const sweep = [full[3] + 220, full[1] - 220];

  return { format, nodes, edges, groups, node, group, nodeState, groupState, edgeState, framings, full, sweep };
};

export const STAGE_COUNT = STAGES.length;
export const stageAt = (t) => {
  let i = -1;
  STAGES.forEach((s, k) => {
    if (t >= s.at) i = k;
  });
  return i;
};
export { clamp };
